import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('sales_data.xlsx')
st = ET.fromstring(z.read('xl/styles.xml'))
z.close()

fmts = st.find('m:numFmts', NS)
print("numFmts:")
if fmts is not None:
    for f in fmts:
        print("  id:", f.get('numFmtId'), "code:", repr(f.get('formatCode')))
else:
    print("  none")

cellxfs = st.find('m:cellXfs', NS)
print("cellXfs count:", len(cellxfs) if cellxfs is not None else 0)
if cellxfs is not None:
    for i, xf in enumerate(cellxfs):
        print("  xf", i, dict(xf.attrib))

